using Maran.Host.Modules;
using Maran.Sdk.Contracts;

namespace Maran.Host.Tests.Modules;

/// <summary>
/// Behavioral contract of <see cref="ModuleFrameDocument"/>: the document of a frame is generated by the
/// panel, pins the entry script by its integrity value, carries nothing inline, and is refused for a
/// description that would put anything else into an attribute.
/// </summary>
public sealed class ModuleFrameDocumentTests
{
    /// <summary>A well-formed SHA-384 integrity value (48 zero bytes).</summary>
    private static readonly string Integrity = "sha384-" + Convert.ToBase64String(new byte[48]);

    /// <summary>The document is the exact markup the contract names: one classic script with its integrity, no inline code.</summary>
    [Fact]
    public void The_document_is_the_generated_page_with_one_pinned_entry_script()
    {
        Assert.True(ModuleFrameDocument.TryRender(Describe("entry.js", Integrity), out var html));

        Assert.Equal(
            "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><title>module</title></head><body>"
            + $"<script src=\"entry.js\" integrity=\"{Integrity}\" crossorigin=\"anonymous\"></script></body></html>",
            html);
    }

    /// <summary>The document holds no inline script, no event handler, no module script, no style and no second script.</summary>
    [Fact]
    public void The_document_has_no_inline_script_handler_or_style()
    {
        ModuleFrameDocument.TryRender(Describe("entry.js", Integrity), out var html);

        Assert.Equal(1, Count(html!, "<script"));
        Assert.Contains("src=\"entry.js\"", html, StringComparison.Ordinal);
        Assert.Contains("integrity=\"sha384-", html, StringComparison.Ordinal);
        Assert.DoesNotContain("type=\"module\"", html, StringComparison.Ordinal);
        Assert.DoesNotContain("<style", html, StringComparison.Ordinal);
        Assert.DoesNotContain("javascript:", html, StringComparison.Ordinal);
        Assert.Contains("></script>", html, StringComparison.Ordinal);
    }

    /// <summary>An entry that is not a plain script file name is refused: a path, a document, a quote that would leave the attribute.</summary>
    /// <param name="entry">An entry a description must not carry.</param>
    [Theory]
    [InlineData("dir/entry.js")]
    [InlineData("../entry.js")]
    [InlineData("entry.html")]
    [InlineData("entry.css")]
    [InlineData("entry\".js")]
    [InlineData("entry.js\"><script>x</script><a b=\"")]
    [InlineData("")]
    public void An_entry_that_is_not_a_plain_script_file_is_refused(string entry)
    {
        Assert.False(ModuleFrameDocument.TryRender(Describe(entry, Integrity), out var html));
        Assert.Null(html);
    }

    /// <summary>An integrity value that is not exactly a SHA-384 digest is refused.</summary>
    /// <param name="integrity">A value a description must not carry.</param>
    [Theory]
    [InlineData("")]
    [InlineData("sha256-AAAA")]
    [InlineData("sha384-")]
    [InlineData("sha384-AAAA")]
    [InlineData("md5-AAAA")]
    [InlineData("sha384-AAAA\" onload=\"x")]
    public void An_integrity_value_that_is_not_a_sha384_digest_is_refused(string integrity)
    {
        Assert.False(ModuleFrameDocument.TryRender(Describe("entry.js", integrity), out _));
    }

    /// <summary>A description with the 48-byte digest is accepted - the control that the refusals above are about the value.</summary>
    [Fact]
    public void A_well_formed_description_is_rendered()
    {
        Assert.True(ModuleFrameDocument.TryRender(Describe("main-2.0.js", Integrity), out var html));
        Assert.Contains("src=\"main-2.0.js\"", html, StringComparison.Ordinal);
    }

    /// <summary>Counts non-overlapping occurrences of a marker.</summary>
    /// <param name="text">The text to search.</param>
    /// <param name="marker">The marker.</param>
    /// <returns>How many times the marker occurs.</returns>
    private static int Count(string text, string marker)
    {
        return text.Split(marker).Length - 1;
    }

    /// <summary>Builds a description with the members a test varies.</summary>
    /// <param name="entry">The entry file name.</param>
    /// <param name="integrity">The integrity value.</param>
    /// <returns>The description.</returns>
    private static ModuleSpaDescription Describe(string entry, string integrity)
    {
        return new ModuleSpaDescription("1.0.0", entry, integrity, ["en"]);
    }
}
